    { const char * tb_v1167 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1167; }
    { const char * tb_v1168 = "TB_COLD TB_API void tb_crash(int line, const char *msg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1168; }
    { const char * tb_v1169 = "    fflush(stdout);\n"; *(const char * *)tb_grow(v_lines) = tb_v1169; }
