    { const char * tb_v1256 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1256; }
    { const char * tb_v1257 = "// поток с 8 МБ стека (на Mac по умолчанию всего 512 КБ) и с понятным сообщением при переполнении\n"; *(const char * *)tb_grow(v_lines) = tb_v1257; }
    { const char * tb_v1258 = "TB_API int tb_thread_create(pthread_t *th, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1258; }
    { const char * tb_v1259 = "    tb_tramp *t = malloc(sizeof(tb_tramp));\n"; *(const char * *)tb_grow(v_lines) = tb_v1259; }
    { const char * tb_v1260 = "    if (!t) return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1260; }
