    { const char * tb_v2647 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2647; }
    { const char * tb_v2648 = "// ---------- dict: ключи и значения лежат в двух списках по порядку добавления,\n"; *(const char * *)tb_grow(v_lines) = tb_v2648; }
    { const char * tb_v2649 = "// а найти номер по ключу можно тремя способами (mode):\n"; *(const char * *)tb_grow(v_lines) = tb_v2649; }
    { const char * tb_v2650 = "//   1 — «номер = адрес»: ключи int шли подряд base, base+1, base+2 ... — номер = ключ - base, без поиска;\n"; *(const char * *)tb_grow(v_lines) = tb_v2650; }
    { const char * tb_v2651 = "//   2 — «адресное хранение»: ключи int лежат плотно — pos[ключ - base] = номер + 1, один взгляд;\n"; *(const char * *)tb_grow(v_lines) = tb_v2651; }
    { const char * tb_v2652 = "//   0 — таблица slots с хешем (текст или разбросанные числа) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2652; }
    { const char * tb_v2653 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v2653; }
    { const char * tb_v2654 = "    tb_list *keys; tb_list *vals; long long *slots; long long nslots; int text;\n"; *(const char * *)tb_grow(v_lines) = tb_v2654; }
    { const char * tb_v2655 = "    int mode; long long base; long long *pos; long long npos;\n"; *(const char * *)tb_grow(v_lines) = tb_v2655; }
    { const char * tb_v2656 = "} tb_dict;\n"; *(const char * *)tb_grow(v_lines) = tb_v2656; }
    { const char * tb_v2657 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2657; }
    { const char * tb_v2658 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v2658; }
    { const char * tb_v2659 = "#define TB_DAT ((1LL << 40) - 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2659; }
    { const char * tb_v2660 = "#define TB_DTAG(h) ((long long)(((h) >> 40) << 40) & ~TB_DAT & 0x7FFFFFFFFFFFFFFFLL)\n"; *(const char * *)tb_grow(v_lines) = tb_v2660; }
    { const char * tb_v2661 = "TB_API unsigned long long tb_hash(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2661; }
    { const char * tb_v2662 = "    unsigned long long h = 1469598103934665603ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2662; }
    { const char * tb_v2663 = "    if (d->text) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2663; }
    { const char * tb_v2664 = "        for (const unsigned char *p = *(const unsigned char * const *)k; *p; p++) { h ^= *p; h *= 1099511628211ULL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2664; }
    { const char * tb_v2665 = "    } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v2665; }
    { const char * tb_v2666 = "        h ^= (unsigned long long)*(const long long *)k;\n"; *(const char * *)tb_grow(v_lines) = tb_v2666; }
    { const char * tb_v2667 = "        h *= 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2667; }
    { const char * tb_v2668 = "        h ^= h >> 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v2668; }
    { const char * tb_v2669 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2669; }
    { const char * tb_v2670 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v2670; }
    { const char * tb_v2671 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2671; }
    { const char * tb_v2672 = "TB_API int tb_keq(tb_dict *d, const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2672; }
    { const char * tb_v2673 = "    if (d->text) return strcmp(*(const char * const *)a, *(const char * const *)b) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2673; }
    { const char * tb_v2674 = "    return *(const long long *)a == *(const long long *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v2674; }
    { const char * tb_v2675 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2675; }
    { const char * tb_v2676 = "TB_INL long long tb_dfind(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2676; }
    { const char * tb_v2677 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2677; }
    { const char * tb_v2678 = "        unsigned long long at = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v2678; }
    { const char * tb_v2679 = "        return at < (unsigned long long)d->keys->len ? (long long)at : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2679; }
    { const char * tb_v2680 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2680; }
    { const char * tb_v2681 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2681; }
    { const char * tb_v2682 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v2682; }
    { const char * tb_v2683 = "        return o < (unsigned long long)d->npos ? d->pos[o] - 1 : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2683; }
    { const char * tb_v2684 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2684; }
    { const char * tb_v2685 = "    unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2685; }
    { const char * tb_v2686 = "    long long tag = TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v2686; }
    { const char * tb_v2687 = "    while (d->slots[i] != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2687; }
    { const char * tb_v2688 = "        long long sl = d->slots[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2688; }
    { const char * tb_v2689 = "        // метка хеша совпала — только тогда сравниваем сами ключи (текст — дорого)\n"; *(const char * *)tb_grow(v_lines) = tb_v2689; }
    { const char * tb_v2690 = "        if ((sl & ~TB_DAT) == tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2690; }
    { const char * tb_v2691 = "            long long at = (sl & TB_DAT) - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2691; }
    { const char * tb_v2692 = "            if (tb_keq(d, d->keys->data + at * d->keys->size, k)) return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v2692; }
    { const char * tb_v2693 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2693; }
    { const char * tb_v2694 = "        i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2694; }
    { const char * tb_v2695 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2695; }
    { const char * tb_v2696 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2696; }
    { const char * tb_v2697 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2697; }
    { const char * tb_v2698 = "// память для таблиц dict — там же, где лежат его ключи (временная или обычная)\n"; *(const char * *)tb_grow(v_lines) = tb_v2698; }
    { const char * tb_v2699 = "TB_API void *tb_dalloc(tb_dict *d, void *old, long long bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2699; }
    { const char * tb_v2700 = "    if (old && !(tb_nchunks > 0 && tb_in_temp(old))) tb_gc_free(old);\n"; *(const char * *)tb_grow(v_lines) = tb_v2700; }
    { const char * tb_v2701 = "    void *p = tb_in_cur_temp(d->keys->data) ? tb_temp_alloc(bytes) : tb_gc_alloc_np(bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v2701; }
    { const char * tb_v2702 = "    if (!p) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2702; }
    { const char * tb_v2703 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2703; }
    { const char * tb_v2704 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2704; }
    { const char * tb_v2705 = "TB_API void tb_dreindex(tb_dict *d, long long nslots) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2705; }
    { const char * tb_v2706 = "    d->mode = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2706; }
    { const char * tb_v2707 = "    if (d->pos) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2707; }
    { const char * tb_v2708 = "        if (!(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v2708; }
    { const char * tb_v2709 = "        d->pos = 0; d->npos = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2709; }
    { const char * tb_v2710 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2710; }
    { const char * tb_v2711 = "    d->nslots = nslots;\n"; *(const char * *)tb_grow(v_lines) = tb_v2711; }
    { const char * tb_v2712 = "    d->slots = tb_dalloc(d, d->slots, nslots * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2712; }
    { const char * tb_v2713 = "    memset(d->slots, 0, nslots * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2713; }
    { const char * tb_v2714 = "    unsigned long long mask = nslots - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2714; }
    { const char * tb_v2715 = "    for (long long at = 0; at < d->keys->len; at++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2715; }
    { const char * tb_v2716 = "        unsigned long long h = tb_hash(d, d->keys->data + at * d->keys->size), i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2716; }
    { const char * tb_v2717 = "        while (d->slots[i] != 0) i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2717; }
    { const char * tb_v2718 = "        d->slots[i] = (at + 1) | TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v2718; }
    { const char * tb_v2719 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2719; }
    { const char * tb_v2720 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2720; }
    { const char * tb_v2721 = "// перейти на таблицу с хешем (ключ ушёл далеко от остальных или его удалили)\n"; *(const char * *)tb_grow(v_lines) = tb_v2721; }
    { const char * tb_v2722 = "TB_API void tb_dto_hash(tb_dict *d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2722; }
    { const char * tb_v2723 = "    long long n = 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v2723; }
    { const char * tb_v2724 = "    while (n < d->keys->len * 2 + 2) n *= 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v2724; }
    { const char * tb_v2725 = "    tb_dreindex(d, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2725; }
    { const char * tb_v2726 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2726; }
    { const char * tb_v2727 = "// mode 2: таблица pos на ключи base .. base+npos-1\n"; *(const char * *)tb_grow(v_lines) = tb_v2727; }
    { const char * tb_v2728 = "TB_API void tb_dto_pos(tb_dict *d, long long npos) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2728; }
    { const char * tb_v2729 = "    long long *p = tb_dalloc(d, 0, npos * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2729; }
    { const char * tb_v2730 = "    memset(p, 0, npos * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2730; }
    { const char * tb_v2731 = "    const long long *ks = (const long long *)d->keys->data;\n"; *(const char * *)tb_grow(v_lines) = tb_v2731; }
    { const char * tb_v2732 = "    for (long long at = 0; at < d->keys->len; at++) p[ks[at] - d->base] = at + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2732; }
    { const char * tb_v2733 = "    if (d->pos && !(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v2733; }
    { const char * tb_v2734 = "    d->pos = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2734; }
