    { const char * tb_v2881 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2881; }
    { const char * tb_v2882 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v2882; }
    { const char * tb_v2883 = "TB_API void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2883; }
