    { const char * tb_v3043 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3043; }
    { const char * tb_v3044 = "// замок в программе: атомарный обмен; занято — сначала коротко ждём, потом уступаем ядро\n"; *(const char * *)tb_grow(v_lines) = tb_v3044; }
    { const char * tb_v3045 = "TB_INL unsigned long tb_lock_take(int *l) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3045; }
    { const char * tb_v3046 = "    while (__atomic_exchange_n(l, 1, __ATOMIC_ACQUIRE)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3046; }
