    { const char * tb_v6371 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6371; }
    { const char * tb_v6372 = "// TB_GPU_CHECK: проба смешивания. Фон — серый d (строка), буква — цвет k, прозрачность a (столбец),\n"; *(const char * *)tb_grow(v_lines) = tb_v6372; }
    { const char * tb_v6373 = "// таблица 256 × 256; окно меньше — несколько кадров. Первый проход цвет 0: видна только часть фона.\n"; *(const char * *)tb_grow(v_lines) = tb_v6373; }
    { const char * tb_v6374 = "// Второй проход цвет 0x808080 проверяет, что видеокарта складывает части как процессор\n"; *(const char * *)tb_grow(v_lines) = tb_v6374; }
    { const char * tb_v6375 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6375; }
    { const char * tb_v6376 = "    int n0 = tb_nimg; size_t p0 = tb_imgpx_n, need = p0 + 2 * 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v6376; }
    { const char * tb_v6377 = "    uint32_t *all = realloc(tb_imgpx, need * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v6377; }
    { const char * tb_v6378 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 2) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v6378; }
    { const char * tb_v6379 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v6379; }
    { const char * tb_v6380 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v6380; }
    { const char * tb_v6381 = "    if (!all || !list) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6381; }
    { const char * tb_v6382 = "    static uint8_t got[256][256];\n"; *(const char * *)tb_grow(v_lines) = tb_v6382; }
    { const char * tb_v6383 = "    long long badk = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6383; }
    { const char * tb_v6384 = "    for (int pass = 0; pass < 2; pass++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6384; }
    { const char * tb_v6385 = "        uint32_t col = pass ? 0x808080u : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6385; }
    { const char * tb_v6386 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v6386; }
    { const char * tb_v6387 = "        for (int d = 0; d < 256; d++) for (int a = 0; a < 256; a++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6387; }
    { const char * tb_v6388 = "            bg[d * 256 + a] = 0xFF000000u | (uint32_t)d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v6388; }
    { const char * tb_v6389 = "            fg[d * 256 + a] = ((uint32_t)a << 24) | col;\n"; *(const char * *)tb_grow(v_lines) = tb_v6389; }
    { const char * tb_v6390 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6390; }
    { const char * tb_v6391 = "        tb_nimg = n0 + 2; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v6391; }
    { const char * tb_v6392 = "        for (int k = 0; k < 2; k++) { tb_imgs[n0 + k].w = 256; tb_imgs[n0 + k].h = 256; tb_imgs[n0 + k].off = (uint32_t)(p0 + (size_t)k * 65536); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6392; }
    { const char * tb_v6393 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6393; }
    { const char * tb_v6394 = "        tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6394; }
    { const char * tb_v6395 = "        for (int ty = 0; ty < 256; ty += tb_gh) for (int tx = 0; tx < 256; tx += tb_gw) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6395; }
    { const char * tb_v6396 = "            tb_gpu_image(n0, -tx, -ty);\n"; *(const char * *)tb_grow(v_lines) = tb_v6396; }
    { const char * tb_v6397 = "            tb_gpu_image_a(n0 + 1, -tx, -ty);\n"; *(const char * *)tb_grow(v_lines) = tb_v6397; }
    { const char * tb_v6398 = "            tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6398; }
    { const char * tb_v6399 = "            if (!tb_gpu_back) { tb_gpu_probing = 0; tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6399; }
    { const char * tb_v6400 = "            for (int y = 0; y < tb_gh && ty + y < 256; y++) for (int x = 0; x < tb_gw && tx + x < 256; x++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6400; }
    { const char * tb_v6401 = "                uint32_t v = tb_gpu_back[(size_t)y * tb_gw + x] & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v6401; }
    { const char * tb_v6402 = "                if (!pass) got[ty + y][tx + x] = (uint8_t)v;\n"; *(const char * *)tb_grow(v_lines) = tb_v6402; }
    { const char * tb_v6403 = "                else {\n"; *(const char * *)tb_grow(v_lines) = tb_v6403; }
    { const char * tb_v6404 = "                    int d = ty + y, a = tx + x;\n"; *(const char * *)tb_grow(v_lines) = tb_v6404; }
    { const char * tb_v6405 = "                    uint32_t want = a == 0 ? (uint32_t)d : (128u * a + 127) / 255 + got[d][a];\n"; *(const char * *)tb_grow(v_lines) = tb_v6405; }
    { const char * tb_v6406 = "                    if (a == 255) want = 128;\n"; *(const char * *)tb_grow(v_lines) = tb_v6406; }
    { const char * tb_v6407 = "                    if (v != (want > 255 ? 255 : want)) badk++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6407; }
    { const char * tb_v6408 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v6408; }
    { const char * tb_v6409 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6409; }
    { const char * tb_v6410 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6410; }
    { const char * tb_v6411 = "        tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6411; }
    { const char * tb_v6412 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6412; }
    { const char * tb_v6413 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6413; }
    { const char * tb_v6414 = "    memcpy(tb_blend_lut, got, sizeof got);\n"; *(const char * *)tb_grow(v_lines) = tb_v6414; }
    { const char * tb_v6415 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6415; }
    { const char * tb_v6416 = "    tb_gpu_first = 1;   // следующий кадр снова начнётся с чёрного, как у процессора\n"; *(const char * *)tb_grow(v_lines) = tb_v6416; }
    { const char * tb_v6417 = "    long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6417; }
    { const char * tb_v6418 = "    for (int d = 0; d < 256; d++) for (int a = 1; a < 255; a++) diff += got[d][a] != (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v6418; }
    { const char * tb_v6419 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6419; }
    { const char * tb_v6420 = "    if (badk || (e && e[0] == '1'))\n"; *(const char * *)tb_grow(v_lines) = tb_v6420; }
    { const char * tb_v6421 = "        fprintf(stderr, \"TB_GPU_CHECK: смешивание: не как округление к ближайшему %lld из 65536, цвет + фон не сходится %lld\\n\", diff, badk);\n"; *(const char * *)tb_grow(v_lines) = tb_v6421; }
    { const char * tb_v6422 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6422; }
    { const char * tb_v6423 = "TB_API void tb_window_open(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6423; }
    { const char * tb_v6424 = "    if (tb_px) { tb_err = \"окно уже открыто\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6424; }
    { const char * tb_v6425 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6425; }
    { const char * tb_v6426 = "    tb_gw = (int)w; tb_gh = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6426; }
    { const char * tb_v6427 = "    tb_px = calloc((size_t)tb_gw * tb_gh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v6427; }
    { const char * tb_v6428 = "    if (!tb_gfx_open(title)) { free(tb_px); tb_px = 0; tb_err = \"не могу открыть окно: нет экрана\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6428; }
    { const char * tb_v6429 = "    if (tb_gpu_on && tb_gpu_check) { tb_gpu_blend_probe(); atexit(tb_gpu_report); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6429; }
