    { const char * tb_v6446 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6446; }
    { const char * tb_v6447 = "TB_API long long tb_window_w(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gw; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6447; }
    { const char * tb_v6448 = "TB_API long long tb_window_h(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gh; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6448; }
    { const char * tb_v6449 = "// частота кадров: -1 — как у экрана (по умолчанию), 0 — сколько успеет, n — n кадров в секунду (set_fps)\n"; *(const char * *)tb_grow(v_lines) = tb_v6449; }
    { const char * tb_v6450 = "TB_API double tb_frame_ms_v = 16.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6450; }
    { const char * tb_v6451 = "TB_API long long tb_fps_want = -1, tb_fps_v = 0, tb_fps_n = 0, tb_fps_t0 = 0, tb_last_us = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6451; }
    { const char * tb_v6452 = "TB_API void tb_set_fps(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6452; }
    { const char * tb_v6453 = "    if (n < 0) n = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6453; }
    { const char * tb_v6454 = "    tb_fps_want = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6454; }
    { const char * tb_v6455 = "    int nosync = n == 0 || getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6455; }
    { const char * tb_v6456 = "    if (nosync != tb_gpu_nosync) { tb_gpu_nosync = nosync; if (tb_gpu_on) tb_gpu_vsync(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6456; }
    { const char * tb_v6457 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6457; }
