    { const char * tb_v6459 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6459; }
    { const char * tb_v6460 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v6460; }
    { const char * tb_v6461 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6461; }
    { const char * tb_v6462 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6462; }
    { const char * tb_v6463 = "    tb_gfx_events();   // здесь показывается прошлый кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v6463; }
    { const char * tb_v6464 = "    tb_zclr = tb_gzclr = 1;   // новый кадр: глубина 3D начинается заново\n"; *(const char * *)tb_grow(v_lines) = tb_v6464; }
    { const char * tb_v6465 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v6465; }
    { const char * tb_v6466 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v6466; }
    { const char * tb_v6467 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6467; }
    { const char * tb_v6468 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6468; }
    { const char * tb_v6469 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6469; }
    { const char * tb_v6470 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v6470; }
    { const char * tb_v6471 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6471; }
    { const char * tb_v6472 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v6472; }
    { const char * tb_v6473 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v6473; }
    { const char * tb_v6474 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v6474; }
    { const char * tb_v6475 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v6475; }
    { const char * tb_v6476 = "    if (period && now - tb_last_us < period) { usleep((useconds_t)(period - (now - tb_last_us))); now = tb_time_us(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6476; }
    { const char * tb_v6477 = "    tb_frame_ms_v = (now - tb_last_us) / 1000.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6477; }
    { const char * tb_v6478 = "    tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v6478; }
    { const char * tb_v6479 = "    if (!tb_fps_t0) tb_fps_t0 = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v6479; }
    { const char * tb_v6480 = "    tb_fps_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6480; }
    { const char * tb_v6481 = "    if (now - tb_fps_t0 >= 1000000) { tb_fps_v = tb_fps_n * 1000000 / (now - tb_fps_t0); tb_fps_n = 0; tb_fps_t0 = now; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6481; }
    { const char * tb_v6482 = "    tb_last_frame = now / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v6482; }
    { const char * tb_v6483 = "    return !tb_gclosed;\n"; *(const char * *)tb_grow(v_lines) = tb_v6483; }
    { const char * tb_v6484 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6484; }
