    { const char * tb_v6486 = "    if (tb_px && x >= 0 && y >= 0 && x < tb_gw && y < tb_gh) tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v6486; }
    { const char * tb_v6487 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6487; }
    { const char * tb_v6488 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v6488; }
    { const char * tb_v6489 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v6489; }
    { const char * tb_v6490 = "#define TB_CPU_DRAW (!tb_gpu_on || tb_gpu_check)\n"; *(const char * *)tb_grow(v_lines) = tb_v6490; }
    { const char * tb_v6491 = "TB_API void tb_clear_window(long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6491; }
    { const char * tb_v6492 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6492; }
    { const char * tb_v6493 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v6493; }
    { const char * tb_v6494 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v6494; }
    { const char * tb_v6495 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6495; }
    { const char * tb_v6496 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6496; }
    { const char * tb_v6497 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6497; }
    { const char * tb_v6498 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6498; }
    { const char * tb_v6499 = "    if (TB_CPU_DRAW) tb_put(x, y, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6499; }
    { const char * tb_v6500 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6500; }
    { const char * tb_v6501 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6501; }
    { const char * tb_v6502 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6502; }
    { const char * tb_v6503 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v6503; }
    { const char * tb_v6504 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6504; }
    { const char * tb_v6505 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6505; }
    { const char * tb_v6506 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6506; }
    { const char * tb_v6507 = "    if (tb_gpu_on) tb_gpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6507; }
    { const char * tb_v6508 = "    if (TB_CPU_DRAW) tb_cpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6508; }
    { const char * tb_v6509 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6509; }
    { const char * tb_v6510 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6510; }
    { const char * tb_v6511 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6511; }
    { const char * tb_v6512 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6512; }
    { const char * tb_v6513 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v6513; }
    { const char * tb_v6514 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v6514; }
    { const char * tb_v6515 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v6515; }
    { const char * tb_v6516 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6516; }
    { const char * tb_v6517 = "            if (i * i + j * j <= r * r + r) tb_put(cx + i, cy + j, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6517; }
    { const char * tb_v6518 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6518; }
    { const char * tb_v6519 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6519; }
    { const char * tb_v6520 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6520; }
    { const char * tb_v6521 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6521; }
    { const char * tb_v6522 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6522; }
    { const char * tb_v6523 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v6523; }
    { const char * tb_v6524 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v6524; }
    { const char * tb_v6525 = "    while (1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6525; }
    { const char * tb_v6526 = "        if (gpu) tb_gpu_rect(x0, y0, 1, 1, c);   // соседние точки склеятся в полоски\n"; *(const char * *)tb_grow(v_lines) = tb_v6526; }
    { const char * tb_v6527 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6527; }
    { const char * tb_v6528 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v6528; }
    { const char * tb_v6529 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v6529; }
    { const char * tb_v6530 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6530; }
    { const char * tb_v6531 = "        if (e2 <= dx) { e += dx; y0 += sy; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6531; }
    { const char * tb_v6532 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6532; }
    { const char * tb_v6533 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6533; }
    { const char * tb_v6534 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v6534; }
    { const char * tb_v6535 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6535; }
    { const char * tb_v6536 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v6536; }
    { const char * tb_v6537 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v6537; }
    { const char * tb_v6538 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v6538; }
    { const char * tb_v6539 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v6539; }
    { const char * tb_v6540 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v6540; }
    { const char * tb_v6541 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6541; }
    { const char * tb_v6542 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v6542; }
    { const char * tb_v6543 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6543; }
    { const char * tb_v6544 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6544; }
    { const char * tb_v6545 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6545; }
    { const char * tb_v6546 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6546; }
    { const char * tb_v6547 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6547; }
    { const char * tb_v6548 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v6548; }
    { const char * tb_v6549 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6549; }
    { const char * tb_v6550 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6550; }
    { const char * tb_v6551 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6551; }
    { const char * tb_v6552 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v6552; }
    { const char * tb_v6553 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v6553; }
    { const char * tb_v6554 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6554; }
