    { const char * tb_v6839 = "// углы сетки после камеры: место перед камерой и на экране (округлённое), глубина D\n"; *(const char * *)tb_grow(v_lines) = tb_v6839; }
    { const char * tb_v6840 = "typedef struct { double cx, cy, cz, sx, sy, dd; long long rx, ry; int front, near_ok; } tb_3v;\n"; *(const char * *)tb_grow(v_lines) = tb_v6840; }
    { const char * tb_v6841 = "TB_API tb_3v *tb_3vs = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6841; }
    { const char * tb_v6842 = "TB_API long long tb_3vcap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6842; }
    { const char * tb_v6843 = "// старый путь (дроби): сетка задевает камеру или край, где целые не годятся — обрезка у камеры и рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v6843; }
    { const char * tb_v6844 = "TB_API long long *tb_3vst = 0, tb_3vgen = 0;   // какой угол уже посчитан в этом вызове\n"; *(const char * *)tb_grow(v_lines) = tb_v6844; }
    { const char * tb_v6845 = "static void tb_draw_mesh_d(tb_mesh *m, double x, double y, double z, double turn, long long t0, long long t1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6845; }
    { const char * tb_v6846 = "    if (m->nv > tb_3vcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6846; }
