    { const char * tb_v6854 = "    double f = tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180), zn = 205.0 / 4096, hw = tb_gw / 2.0, hh = tb_gh / 2.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6854; }
    { const char * tb_v6855 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;   // та же рамка, что в tb_poly_draw\n"; *(const char * *)tb_grow(v_lines) = tb_v6855; }
    { const char * tb_v6856 = "    if (gx1 > 8192) gx1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v6856; }
    { const char * tb_v6857 = "    if (gy1 > 8192) gy1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v6857; }
    { const char * tb_v6858 = "    // 1) каждый угол нужных треугольников (один раз): поворот, место в мире, взгляд камеры, экран\n"; *(const char * *)tb_grow(v_lines) = tb_v6858; }
    { const char * tb_v6859 = "    for (long long t = t0; t < t1; t++) for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6859; }
    { const char * tb_v6860 = "        long long k = m->t[3 * t + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6860; }
    { const char * tb_v6861 = "        if (tb_3vst[k] == gen) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v6861; }
    { const char * tb_v6862 = "        tb_3vst[k] = gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v6862; }
