    { const char * tb_v6865 = "        double wx = p[0] * ca + p[2] * sa + x - tb_cam[0], wy = p[1] + y - tb_cam[1], wz = -p[0] * sa + p[2] * ca + z - tb_cam[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v6865; }
    { const char * tb_v6866 = "        v->cx = wx * tb_cam[3] + wy * tb_cam[4] + wz * tb_cam[5];\n"; *(const char * *)tb_grow(v_lines) = tb_v6866; }
    { const char * tb_v6867 = "        v->cy = wx * tb_cam[6] + wy * tb_cam[7] + wz * tb_cam[8];\n"; *(const char * *)tb_grow(v_lines) = tb_v6867; }
    { const char * tb_v6868 = "        v->cz = wx * tb_camf[0] + wy * tb_camf[1] + wz * tb_camf[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v6868; }
    { const char * tb_v6869 = "        v->front = v->cz >= zn;\n"; *(const char * *)tb_grow(v_lines) = tb_v6869; }
    { const char * tb_v6870 = "        v->near_ok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6870; }
    { const char * tb_v6871 = "        if (v->front) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6871; }
