    { const char * tb_v6875 = "            v->dd = (1 - zn * iz) * 16777216.0;   // D = (1 - zn / z) * 2^24 — по экрану меняется ровно по плоскости\n"; *(const char * *)tb_grow(v_lines) = tb_v6875; }
    { const char * tb_v6876 = "            v->near_ok = v->sx >= gx0 && v->sx <= gx1 && v->sy >= gy0 && v->sy <= gy1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6876; }
    { const char * tb_v6877 = "            if (v->near_ok) { v->rx = tb_rnd(v->sx); v->ry = tb_rnd(v->sy); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6877; }
    { const char * tb_v6878 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6878; }
