    { const char * tb_v6883 = "        tb_3v *v0 = &tb_3vs[ti[0]], *v1 = &tb_3vs[ti[1]], *v2 = &tb_3vs[ti[2]];\n"; *(const char * *)tb_grow(v_lines) = tb_v6883; }
    { const char * tb_v6884 = "        uint32_t pl[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v6884; }
