    { const char * tb_v7029 = "            tb_grec_p[tb_gslot * TB_GR_CAP + go->ri] = go->rec;\n"; *(const char * *)tb_grow(v_lines) = tb_v7029; }
    { const char * tb_v7030 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7030; }
    { const char * tb_v7031 = "        tb_ginst *g = tb_gin ? &tb_gi[tb_gin - 1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7031; }
    { const char * tb_v7032 = "        if (g && g->m == 3u && g->x0 == (int32_t)go->id && g->y0 == go->cull && g->ox == t0 && g->oy == tn &&\n"; *(const char * *)tb_grow(v_lines) = tb_v7032; }
    { const char * tb_v7033 = "            g->x1 + g->y1 == go->ri && (long long)(g->y1 + 1) * tn < 2000000000) g->y1++;   // та же сетка подряд: одним вызовом\n"; *(const char * *)tb_grow(v_lines) = tb_v7033; }
    { const char * tb_v7034 = "        else tb_gpu_add(go->id, go->cull, go->ri, 1, t0, tn, 0, 3u);\n"; *(const char * *)tb_grow(v_lines) = tb_v7034; }
    { const char * tb_v7035 = "        m->gused = tb_gbatch;\n"; *(const char * *)tb_grow(v_lines) = tb_v7035; }
