    { const char * tb_v7043 = "        tb_3ist = (long long *)realloc(tb_3ist, sizeof(long long) * tb_3icap / 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v7043; }
    { const char * tb_v7044 = "        memset(tb_3ist, 0, sizeof(long long) * (tb_3icap / 3));\n"; *(const char * *)tb_grow(v_lines) = tb_v7044; }
    { const char * tb_v7045 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7045; }
    { const char * tb_v7046 = "    long long fq = tb_m3_f(), gen = ++tb_3igen;\n"; *(const char * *)tb_grow(v_lines) = tb_v7046; }
    { const char * tb_v7047 = "    for (long long t = t0; t < t0 + tn; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7047; }
    { const char * tb_v7048 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v7048; }
    { const char * tb_v7049 = "        for (int i = 0; i < 3; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7049; }
    { const char * tb_v7050 = "            if (tb_3ist[ti[i]] != gen) { tb_3ist[ti[i]] = gen; tb_m3_corner(go->rec.r, m->vi + 4 * ti[i], fq, tb_3i + 3 * ti[i]); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7050; }
