    { const char * tb_v7053 = "        if (tb_m3_tri(tb_3i + 3 * ti[0], tb_3i + 3 * ti[1], tb_3i + 3 * ti[2], go->cull, q, pl)) tb_tri_draw_x(q, m->c[t], pl, gpu, cpu);\n"; *(const char * *)tb_grow(v_lines) = tb_v7053; }
