    { const char * tb_v7056 = "// куски сетки: треугольники делятся пополам по самой длинной стороне, пока в куске не больше 256.\n"; *(const char * *)tb_grow(v_lines) = tb_v7056; }
    { const char * tb_v7057 = "// Треугольники переставляются так, чтобы каждый кусок шёл подряд; у каждого куска свой шар\n"; *(const char * *)tb_grow(v_lines) = tb_v7057; }
    { const char * tb_v7058 = "static int tb_kd_ax;\n"; *(const char * *)tb_grow(v_lines) = tb_v7058; }
    { const char * tb_v7059 = "static const float *tb_kd_c;\n"; *(const char * *)tb_grow(v_lines) = tb_v7059; }
    { const char * tb_v7060 = "static int tb_kd_cmp(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7060; }
    { const char * tb_v7061 = "    float x = tb_kd_c[3 * *(const uint32_t *)a + tb_kd_ax], y = tb_kd_c[3 * *(const uint32_t *)b + tb_kd_ax];\n"; *(const char * *)tb_grow(v_lines) = tb_v7061; }
