    { const char * tb_v7063 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7063; }
    { const char * tb_v7064 = "static void tb_kd(tb_mesh *m, uint32_t *ix, long long n, const float *cen, long long *at) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7064; }
    { const char * tb_v7065 = "    if (n <= 256) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7065; }
    { const char * tb_v7066 = "        long long c = m->nch++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7066; }
    { const char * tb_v7067 = "        m->chr[2 * c] = *at; m->chr[2 * c + 1] = n; *at += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7067; }
